package com.bank.risk.stream;

import com.bank.risk.model.Trade;
import java.util.List;
import java.util.concurrent.SubmissionPublisher;

// A JDK Flow.Publisher of trades (SubmissionPublisher IS a Flow.Publisher).
// Used to PROVE the shared contract: a Reactor Flux can consume it directly.
public class TradePublisher {
    public SubmissionPublisher<Trade> create(List<Trade> trades) {
        SubmissionPublisher<Trade> publisher = new SubmissionPublisher<>();
        // Submit on a separate thread so subscription is wired first.
        new Thread(() -> {
            trades.forEach(publisher::submit);
            publisher.close();
        }).start();
        return publisher;
    }
}
