package com.bank.risk.stream;

import com.bank.risk.model.Trade;
import java.math.BigDecimal;
import java.util.List;
import java.util.concurrent.SubmissionPublisher;
import java.util.logging.Logger;
import reactor.adapter.JdkFlowAdapter;
import reactor.core.publisher.Flux;

// Reactor reason-to-exist: operators on top of the SAME Reactive Streams contract.
public class ReactorBridgeDemo {
    private static final Logger log = Logger.getLogger(ReactorBridgeDemo.class.getName());

    public void run() {
        List<Trade> trades = List.of(
            new Trade("TRD-1", "SAV2001", new BigDecimal("500000")),
            new Trade("TRD-2", "CUR3001", new BigDecimal("50000")),
            new Trade("TRD-3", "SAV2001", new BigDecimal("1200000")));

        SubmissionPublisher<Trade> jdkPublisher = new TradePublisher().create(trades);

        // Adapt the JDK Flow.Publisher into a Reactor Flux — shared contract.
        Flux<Trade> flux = JdkFlowAdapter.flowPublisherToFlux(jdkPublisher);

        flux.filter(t -> t.notional().compareTo(new BigDecimal("100000")) > 0)  // large only
            .map(t -> "RISK-REVIEW " + t.tradeId() + " notional=" + t.notional()) // transform
            .doOnNext(log::info)
            .blockLast();  // demo only — block until stream done
    }
}
