package com.bank.risk.compose;

import com.bank.risk.model.Account;
import com.bank.risk.model.Statement;
import java.math.BigDecimal;
import java.util.concurrent.CompletableFuture;
import java.util.logging.Logger;

// CompletableFuture reason-to-exist: ONE result (or a few parallel calls) joined once.
public class CompletableFutureDemo {
    private static final Logger log = Logger.getLogger(CompletableFutureDemo.class.getName());

    public String buildDashboard(String accountId) {
        CompletableFuture<Account> accountF =
            CompletableFuture.supplyAsync(() -> loadAccount(accountId));
        CompletableFuture<Statement> statementF =
            CompletableFuture.supplyAsync(() -> loadStatement(accountId));

        // Two independent async calls joined ONCE — no stream, no backpressure.
        return accountF.thenCombine(statementF,
                (acct, stmt) -> "DASHBOARD " + acct.holderName()
                        + " balance=" + acct.balance() + " | " + stmt.lastLine())
                .join();
    }

    private Account loadAccount(String id) {
        sleep(40);
        return new Account(id, id.equals("SAV2001") ? "Rajesh" : "Priya",
                id.equals("SAV2001") ? new BigDecimal("1000000") : new BigDecimal("250000"));
    }

    private Statement loadStatement(String id) {
        sleep(40);
        return new Statement(id, "Last txn: Rs.50000 transfer");
    }

    private void sleep(long ms) {
        try { Thread.sleep(ms); } catch (InterruptedException e) { Thread.currentThread().interrupt(); }
    }
}
