package com.bank.risk.batch;

import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.logging.Logger;
import java.util.stream.IntStream;

// Virtual threads reason-to-exist: many BLOCKING tasks, written as simple code,
// scaling like async WITHOUT the reactive complexity.
public class VirtualThreadDemo {
    private static final Logger log = Logger.getLogger(VirtualThreadDemo.class.getName());

    public int scoreAll(int accountCount) {
        AtomicInteger flagged = new AtomicInteger();
        try (ExecutorService vt = Executors.newVirtualThreadPerTaskExecutor()) {
            IntStream.range(0, accountCount).forEach(i ->
                vt.submit(() -> {
                    int score = blockingScore("ACC-" + i);  // ordinary blocking call
                    if (score > 80) flagged.incrementAndGet();
                }));
        } // close() waits for all virtual threads to finish
        log.info(() -> "Scored " + accountCount + " accounts, flagged=" + flagged.get());
        return flagged.get();
    }

    // Simulates a slow external fraud-scoring call that BLOCKS.
    private int blockingScore(String accountId) {
        try { Thread.sleep(20); } catch (InterruptedException e) { Thread.currentThread().interrupt(); }
        return accountId.hashCode() & 0x7f;  // 0..127 pseudo score
    }
}
