    @Test
    void completableFutureCombinesAccountAndStatement() {
        String dashboard = new CompletableFutureDemo().buildDashboard("SAV2001");
        assertTrue(dashboard.contains("Rajesh"));
        assertTrue(dashboard.contains("1000000"));
    }

    @Test
    void virtualThreadsScoreManyAccountsWithoutThreadExhaustion() {
        int flagged = new VirtualThreadDemo().scoreAll(5_000);
        assertTrue(flagged >= 0 && flagged <= 5_000);
    }
}
